ROOT=Path(__file__).resolve().parents[1]; DIST=ROOT/'dist'; OUT=DIST/'downloads'; DATA=json.loads((ROOT/'evidence/project-data.json').read_text()); TESTS=json.loads((ROOT/'evidence/test-results.json').read_text())

def table(headers,rows):
    return '<div class="table-scroll" tabindex="0" role="region" aria-label="Scrollable evidence table"><table><thead><tr>'+''.join('<th scope="col">'+e(str(x))+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+e(str(x))+'</td>' for x in r)+'</tr>' for r in rows)+'</tbody></table></div>'
def p(text):return '<p>'+e(text)+'</p>'
def h(text):return '<h3>'+e(text)+'</h3>'
def bullets(items):return '<ul>'+''.join('<li>'+e(x)+'</li>' for x in items)+'</ul>'

def diagram(name,future):
    lanes=['Requester','Service coordinator','ICT technician','Register / system']; width,height=1060,810
    if future:
        nodes=[('a',0,110,['Submit structured fault','or assisted intake']),('b',3,110,['Validate details','reference and priority']),('c',1,260,['Triage and assign','named technician']),('d',2,260,['Start work','In progress']),('f',2,440,['Propose resolution','record evidence']),('g',0,440,['Service restored?','confirm or reject']),('z',3,660,['Close on confirmation','review queue trends'])]
        edges=[('a','b',[(230,142),(830,142)],'Submit'),('b','c',[(925,174),(925,220),(405,220),(405,260)],'Valid'),('b','a',[(925,174),(925,195),(145,195),(145,174)],'Invalid: correct details'),('c','d',[(490,292),(570,292)],'Assigned'),('d','f',[(665,324),(665,440)],'Work completed'),('f','g',[(570,472),(230,472)],'Awaiting confirmation'),('g','z',[(145,504),(145,692),(830,692)],'Yes: confirm'),('g','d',[(50,472),(35,472),(35,385),(665,385),(665,324)],'No: reason required; return to work')]
        notes=['Proposed process. All state changes append a demo event.','Target timer continues while awaiting confirmation. No automatic closure.']
    else:
        nodes=[('a',0,110,['Detect fault','email or phone']),('b',1,110,['Re-enter details','into spreadsheet']),('c',1,280,['Clarify and prioritise','manual follow-up']),('d',0,280,['Supply missing details','or chase status']),('f',2,450,['Diagnose and repair','inform coordinator']),('g',1,450,['Update spreadsheet','close without confirmation']),('z',0,660,['Discover unresolved fault','send another email'])]
        edges=[('a','b',[(230,142),(310,142)],''),('b','c',[(405,174),(405,280)],''),('c','d',[(310,312),(230,312)],'Missing information'),('d','c',[(145,344),(145,385),(405,385),(405,344)],'Clarification'),('c','f',[(490,312),(665,312),(665,450)],'Assign via email'),('f','g',[(570,482),(490,482)],'Repair note'),('g','z',[(405,514),(405,620),(145,620),(145,660)],'If service still fails'),('z','a',[(50,692),(32,692),(32,80),(145,80),(145,110)],'Repeat report')]
        notes=['Invented current state for analysis; not an actual QPS process.','Spreadsheet updates have no dependable ownership or protected history.']
    svg=[f'<svg xmlns="http://www.w3.org/2000/svg" width="{width}" height="{height}" viewBox="0 0 {width} {height}" role="img" aria-label="{name.replace("-"," ")} swimlane process"><defs><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0 0L10 5L0 10z" fill="#47648a"/></marker></defs><rect width="1060" height="810" fill="white"/>']
    mx=Element('mxfile',host='app.diagrams.net',type='device'); di=SubElement(mx,'diagram',name=name); model=SubElement(di,'mxGraphModel',dx='1060',dy='810',grid='1',gridSize='10',page='1',pageWidth='1060',pageHeight='810'); rt=SubElement(model,'root');SubElement(rt,'mxCell',id='0');SubElement(rt,'mxCell',id='1',parent='0')
    for i,l in enumerate(lanes):
        x=20+i*260;svg.append(f'<rect x="{x}" y="20" width="240" height="730" fill="{("#f5f8ff" if i%2==0 else "#fafbfd")}" stroke="#dbe2eb"/><rect x="{x}" y="20" width="240" height="45" fill="#edf2f8"/><text x="{x+120}" y="49" text-anchor="middle" font-family="Arial" font-size="17" font-weight="bold" fill="#132333">{e(l)}</text>')
        cell=SubElement(rt,'mxCell',id='lane'+str(i),value=l,style='swimlane;horizontal=1;startSize=45;fillColor=#f5f8ff;strokeColor=#dbe2eb;fontSize=17;',vertex='1',parent='1');SubElement(cell,'mxGeometry',x=str(x),y='20',width='240',height='730',attrib={'as':'geometry'})
    for a,b,pts,label in edges:
        points=' '.join(f'{x},{y}' for x,y in pts);svg.append(f'<polyline points="{points}" fill="none" stroke="#47648a" stroke-width="2" marker-end="url(#arrow)"/>')
        if label:
            x,y=pts[len(pts)//2];
            if len(pts)==2:x=(pts[0][0]+pts[1][0])/2;y=(pts[0][1]+pts[1][1])/2
            if 'No:' in label:x=380;y=374
            if 'Invalid' in label:x=600;y=187
            if 'Yes:' in label:x=510;y=684
            if 'Repeat' in label:x=90;y=760
            svg.append(f'<text x="{x}" y="{y-9}" text-anchor="middle" font-family="Arial" font-size="14" fill="#30466f" style="paint-order:stroke;stroke:white;stroke-width:5px;stroke-linejoin:round">{e(label)}</text>')
        cell=SubElement(rt,'mxCell',id=a+'_'+b,value=label,style='edgeStyle=orthogonalEdgeStyle;rounded=0;endArrow=block;strokeColor=#47648a;fontSize=14;',edge='1',source=a,target=b,parent='1');geo=SubElement(cell,'mxGeometry',relative='1',attrib={'as':'geometry'});arr=SubElement(geo,'Array',attrib={'as':'points'});[SubElement(arr,'mxPoint',x=str(x),y=str(y)) for x,y in pts[1:-1]]
    for id,lane,y,lines in nodes:
        x=50+lane*260;svg.append(f'<rect x="{x}" y="{y}" width="180" height="64" rx="7" fill="white" stroke="#174acb" stroke-width="1.5"/>');svg.append(f'<text x="{x+90}" y="{y+26}" text-anchor="middle" font-family="Arial" font-size="16" fill="#132333">{e(lines[0])}</text><text x="{x+90}" y="{y+47}" text-anchor="middle" font-family="Arial" font-size="14" fill="#526170">{e(lines[1])}</text>')
        cell=SubElement(rt,'mxCell',id=id,value='\n'.join(lines),style='rounded=1;whiteSpace=wrap;html=0;fillColor=#ffffff;strokeColor=#174acb;fontSize=16;',vertex='1',parent='1');SubElement(cell,'mxGeometry',x=str(x),y=str(y),width='180',height='64',attrib={'as':'geometry'})
    for j,note in enumerate(notes):svg.append(f'<text x="20" y="{782+j*19}" font-family="Arial" font-size="13" fill="#526170">{e(note)}</text>')
    svg.append('</svg>');(OUT/(name+'.svg')).write_text(''.join(svg));(OUT/(name+'.drawio')).write_bytes(tostring(mx,encoding='utf-8',xml_declaration=True))
for name,future in [('current-state',False),('future-state',True)]:diagram(name,future)

SECTIONS=[]
def section(id,title,html):SECTIONS.append((id,title,html))
section('discovery','Stakeholders and problem analysis',p('Problem statement: fragmented fault intake and unconfirmed closure create avoidable administration and uncertain service restoration. The proposed service gives staff one visible request, a named owner and a confirmed outcome.')+p('Scope: routine device, access, application and network faults in three fictional licensing support units. Exclusions: weapons licensing decisions, applicant records, exhibits, emergency response, security incident handling, live integrations, procurement and real staff data. Security or safety incidents must use authorised agency channels rather than this proposed routine workflow.')+p('All seven stakeholder groups, six findings and the 50-fault baseline are simulated. In a real engagement, obtain informed participation, validate notes, invite dissent and triangulate interviews with observation and service data before baselining requirements.')+h('Stakeholder map and engagement plan')+table(['ID','Stakeholder','Influence and impact','Needs','Engagement','Validation role'],DATA['stakeholders'])+h('Interview questions')+bullets(DATA['questions'])+h('Simulated interview findings')+table(['ID','Perspective','Fictional observation','Design implication','Evidence status'],DATA['findings'])+h('Success measures')+p('The baseline below is an invented four-week sample of 50 faults, separate from the eight seeded prototype records. Targets are hypotheses to validate in a comparable four-week pilot. No operational benefits have been measured.')+table(['ID','Measure','Synthetic baseline','Proposed target','Measurement and owner'],DATA['metrics'])+h('Assumptions and validation backlog')+bullets(['A01: 50 routine faults per month and 12 minutes active handling per fault. Validate through a time-and-motion baseline; do not include technician repair time.','A02: staff have an approved device and platform access. Confirm with the platform owner and include an assisted channel.','A03: a business owner can define priorities and organise requester confirmation. Validate with all shifts and the coordinator.','A04: existing approved service tooling may meet the need. Assess before building or procuring another platform.','A05: policies, retention rules, real data classification and supplier arrangements are unknown. Obtain authoritative agency decisions before a pilot.']))
section('process','Current and future process analysis',p('These simplified swimlanes show responsibilities and hand-offs; they are not asserted to be BPMN 2.0 compliant or to describe actual QPS processes. Open the SVG for a larger view, or edit the diagrams.net source.')+h('Current state')+'<img class="diagram" src="downloads/current-state.svg" alt="Current state swimlane: email intake, manual clarification, spreadsheet closure and repeated fault reports."><div class="diagram-links"><a href="downloads/current-state.svg">Open current-state SVG</a><a href="downloads/current-state.drawio" download>Edit current-state draw.io</a></div>'+h('Proposed future state')+'<img class="diagram" src="downloads/future-state.svg" alt="Future state swimlane: structured intake, validation, assignment, resolution and requester confirmation with rejection loop."><div class="diagram-links"><a href="downloads/future-state.svg">Open future-state SVG</a><a href="downloads/future-state.drawio" download>Edit future-state draw.io</a></div>'+h('Gap analysis')+table(['Gap','Current state','Problem or risk','Proposed improvement','Findings','Requirements','Measures'],DATA['gaps'])+p('Priority definitions and timing are proposed business rules. High impact means multiple staff blocked; High urgency means no practical workaround. P1 = both High (4 elapsed hours); P2 = either High (24 hours); P3 = neither High (72 hours). The timer does not pause for confirmation. Capacity and escalation arrangements need sponsor validation.'))
reqhtml=p('BRD purpose: define a testable service workflow for the fictional problem. Baseline version 1.0 is ready for portfolio review; business approval is not claimed. Must for pilot controls remain mandatory gates even though this prototype does not implement them.')+h('Business outcomes and solution boundary')+p('Reduce handling and chasing, improve submission quality and verify restoration. The working prototype is static HTML, CSS and JavaScript with a browser-local dataset. It demonstrates service behaviour, not production identity, protected audit, cross-device persistence or a deployed Microsoft 365 solution.')
for r in DATA['requirements']:reqhtml+=f'<article class="story" id="{r["id"]}"><span class="tag blue">{r["id"]} · {e(r["priority"])} · {e(r["type"])}</span><h3>{e(r["story"])}</h3><p><strong>Acceptance criteria:</strong> {e(r["ac"])}</p><p class="small muted">{e(r["delivery"])} · Gap {r["gap"]} · Tests {e(r["tests"])}</p></article>'
reqhtml+=h('Data dictionary')+table(['Field','Type','Definition and validation'],DATA['dictionary'])+h('Requirements traceability matrix')+table(['Requirement','Gap','Priority','Test coverage','Delivery status'],[[r['id'],r['gap'],r['priority'],r['tests'],r['delivery']] for r in DATA['requirements']])+'<p><a href="downloads/requirements-traceability.csv" download>Download traceability CSV</a></p>'+h('Microsoft 365 implementation blueprint')+p('First assess the approved service management platform. If it cannot meet the need, test a low-code alternative in an approved tenant: Power Apps for intake, SharePoint or Microsoft Lists for the request register, a separate event list for state history, Power Automate for controlled notifications and escalation, and Power BI for trends. No tenant configuration or licensing has been performed in this portfolio.')+bullets(['Design Request and RequestEvent lists with stable IDs, controlled choice columns, UTC timestamps and indexed filter fields; confirm delegation and realistic list volumes.','Use agency SSO and group-based permissions; implement requester and assigned-technician restrictions in the data/service layer. Hiding controls in Power Apps is insufficient.','Make state transitions server-validated and protect the event repository from end-user modification; use concurrency checks and idempotent flows to prevent duplicate events.','Configure retention and record capture with the records owner; do not assume a SharePoint version history is sufficient. Validate tenant location, connector paths and supplier terms.','Test notification failures, flow retries, backup/restore, operational support and licensing before pilot. The web demo does not send email or run automatic escalation.'])
section('requirements','Business requirements and traceability',reqhtml)
section('governance','Governance risk and compliance',p('This is a control mapping and validation plan, not a compliance certification or legal interpretation. The current public sources were reviewed on 9 October 2026. Agency owners must confirm applicability and internal policy requirements.')+table(['Framework','Application to this project','Required evidence','Requirements','Sources'],DATA['controls'])+h('Risk register')+p('Likelihood and impact use 1–5 scales. Score = likelihood × impact; Low 1–4, Medium 5–9, High 10–25. Ratings are scenario estimates, not agency assessments. Residual High risks K02 and K07 remain unacceptable for production and are explicit release gates.')+table(['ID','Risk','Inherent score','Mitigation','Owner','Residual score','Acceptance or gate'],DATA['risks'])+h('Document control')+table(['Version','Date','Change','Status'],[['0.1','9 Oct 2026','Scenario, findings and process baseline drafted','Superseded draft'],['0.9','9 Oct 2026','Prototype, requirements and governance mapped','Superseded draft'],['1.0','9 Oct 2026','Executed prototype tests and packaged portfolio evidence','Portfolio review baseline; no agency approval']])+table(['Approver role','Decision required','Status'],[['Project author','Portfolio baseline and disclosure accuracy','Prepared for review'],['Business sponsor','Scope, success measures, funding and residual risks','Not sought; fictional project'],['Security / privacy / records owners','Applicable controls and assessment evidence','Not sought; no agency implementation'],['Business UAT lead','Pilot acceptance and rollout readiness','Not executed']])+h('Version and change practice')+p('Keep requirements, maps, decisions, source and test evidence in version control. A change request records problem, affected requirement IDs, benefit, risk, owner and acceptance impact. Assess it with the process owner, update traceability and tests, then baseline a reviewed release. Operational records require their own approved records repository; source control is not a substitute.')+h('Decision log')+table(['ID','Decision','Reason','Status'],DATA['decisions']))
